export type Cell = [number, number];

export function nextGeneration(cells: Cell[]): Cell[] {
  return [];
}

import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - nextGeneration", () => {
  // Simplest cases
  it("should return empty array when given empty array -- []", () => {
    expect(nextGeneration([])).toEqual([]);
  });
  it.todo("should kill a single live cell with 0 neighbors -- [(0,0)] -> []");

  // Rule 1: Underpopulation (< 2 neighbors dies)
  it.todo("should kill two adjacent live cells each with 1 neighbor -- [(0,1),(1,1)] -> []");

  // Rule 4: Reproduction (dead cell with exactly 3 neighbors becomes alive)
  it.todo("should bring a dead cell with exactly 3 live neighbors to life -- Rule 4 example");

  // Rule 2: Survival (2 or 3 neighbors lives on)
  it.todo("should keep a live cell with 3 neighbors alive -- Rule 2 example, center (1,1) survives");

  // Rule 3: Overpopulation (> 3 neighbors dies)
  it.todo("should kill a live cell with 4 neighbors -- Rule 3 example, center (1,1) dies");

  // Pattern: Block (still life)
  it.todo("should keep a block unchanged -- [(0,0),(1,0),(0,1),(1,1)] -> same");

  // Pattern: Blinker (oscillator)
  it.todo("should oscillate a vertical blinker to horizontal -- [(0,0),(0,1),(0,2)] -> [(-1,1),(0,1),(1,1)]");

  // Negative coordinates
  it.todo("should handle negative coordinates -- blinker around origin works with negatives");
});

